    --header "Content-Type: multipart/form-data" \
    --header "Accept: application/json" \
    --form "title=Lâmpada queimada no bloco A"\
    --form "description=A lâmpada do corredor do primeiro andar do bloco A está queimada."\
    --form "priority=medium"\
    --form "photo_descriptions[]=Foto da lâmpada queimada"\
    --form "photos[]=@/private/var/folders/m6/1rpjlk0j0l3b1db7xjpphzt80000gn/T/phps2hr5i440voodJGhNeV" </code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://localhost/api/occurrences"
);

const headers = {
    "Content-Type": "multipart/form-data",
    "Accept": "application/json",
};

const body = new FormData();
body.append('title', 'Lâmpada queimada no bloco A');
body.append('description', 'A lâmpada do corredor do primeiro andar do bloco A está queimada.');
body.append('priority', 'medium');
body.append('photo_descriptions[]', 'Foto da lâmpada queimada');
body.append('photos[]', document.querySelector('input[name="photos[]"]').files[0]);

fetch(url, {
    method: "POST",
    headers,
    body,
}).then(response =&gt; response.json());</code></pre></div>

